using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    /// <summary>
    /// Factory for creating in-memory SchoolContext instances for testing.
    /// Each call to Create() returns a fresh database.
    /// </summary>
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithSeedData(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            // Departments
            var dept1 = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            var dept2 = new Department
            {
                DepartmentID = 2,
                Name = "Mathematics",
                Budget = 80000m,
                StartDate = new DateTime(2019, 6, 1)
            };
            context.Departments.AddRange(dept1, dept2);

            // Instructors
            var instructor1 = new Instructor
            {
                ID = 100,
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = new DateTime(2015, 8, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 100, Location = "Room 101" }
            };
            var instructor2 = new Instructor
            {
                ID = 101,
                LastName = "Jones",
                FirstMidName = "Jane",
                HireDate = new DateTime(2018, 1, 15),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.AddRange(instructor1, instructor2);

            // Courses
            var course1 = new Course
            {
                CourseID = 1001,
                Title = "Calculus",
                Credits = 4,
                DepartmentID = 2,
                Department = dept2,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 1002,
                Title = "Physics",
                Credits = 3,
                DepartmentID = 1,
                Department = dept1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.AddRange(course1, course2);

            // Course Assignments
            var ca1 = new CourseAssignment { CourseID = 1001, InstructorID = 100 };
            var ca2 = new CourseAssignment { CourseID = 1002, InstructorID = 101 };
            instructor1.CourseAssignments.Add(ca1);
            instructor2.CourseAssignments.Add(ca2);
            context.CourseAssignments.AddRange(ca1, ca2);

            // Students
            var student1 = new Student
            {
                ID = 1,
                LastName = "Alexander",
                FirstMidName = "Carson",
                EnrollmentDate = new DateTime(2021, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            var student2 = new Student
            {
                ID = 2,
                LastName = "Baker",
                FirstMidName = "Alice",
                EnrollmentDate = new DateTime(2022, 1, 15),
                Enrollments = new List<Enrollment>()
            };
            var student3 = new Student
            {
                ID = 3,
                LastName = "Adams",
                FirstMidName = "Bob",
                EnrollmentDate = new DateTime(2021, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            context.Students.AddRange(student1, student2, student3);

            // Enrollments
            var enrollment1 = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 1001,
                StudentID = 1,
                Grade = Grade.A,
                Course = course1,
                Student = student1
            };
            var enrollment2 = new Enrollment
            {
                EnrollmentID = 2,
                CourseID = 1002,
                StudentID = 2,
                Grade = Grade.B,
                Course = course2,
                Student = student2
            };
            student1.Enrollments.Add(enrollment1);
            student2.Enrollments.Add(enrollment2);
            course1.Enrollments.Add(enrollment1);
            course2.Enrollments.Add(enrollment2);
            context.Enrollments.AddRange(enrollment1, enrollment2);

            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue so tests don't interfere with each other
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain again after test
            while (_sut.ReceiveNotification() != null) { }
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            // Act
            _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("Student 'John Doe'", notification.Message);
            Assert.Contains("has been created", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("101", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("(ID: 101)", notification.Message);
            Assert.Contains("has been updated", notification.Message);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            // Act
            _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("DELETE", notification.Operation);
            Assert.Contains("has been deleted", notification.Message);
            Assert.Contains("Department 'Engineering'", notification.Message);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            // Act
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToNonDefault()
        {
            var before = DateTime.Now.AddSeconds(-1);

            // Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            var after = DateTime.Now.AddSeconds(1);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void ReceiveNotification_WhenEmpty_ReturnsNull()
        {
            // Assert - queue is drained in constructor
            var notification = _sut.ReceiveNotification();
            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_DequeuedInFifoOrder()
        {
            // Arrange
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            // Act & Assert
            var first = _sut.ReceiveNotification();
            Assert.NotNull(first);
            Assert.Equal("A", first.EntityType);

            var second = _sut.ReceiveNotification();
            Assert.NotNull(second);
            Assert.Equal("B", second.EntityType);

            var third = _sut.ReceiveNotification();
            Assert.NotNull(third);
            Assert.Equal("C", third.EntityType);

            var fourth = _sut.ReceiveNotification();
            Assert.Null(fourth);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act - should be a no-op but not throw
            var ex = Record.Exception(() => _sut.MarkAsRead(42));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_MultipleMessages_AllEnqueued()
        {
            // Arrange & Act
            for (int i = 0; i < 5; i++)
            {
                _sut.SendNotification("Type", i.ToString(), EntityOperation.CREATE);
            }

            // Assert
            int count = 0;
            while (_sut.ReceiveNotification() != null)
                count++;
            Assert.Equal(5, count);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _sut.SendNotification("Student", "99", "", EntityOperation.UPDATE, "User1");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("(ID: 99)", notification.Message);
        }

        [Fact]
        public void SendNotification_WithWhitespaceDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _sut.SendNotification("Student", "99", "   ", EntityOperation.UPDATE, "User1");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("(ID: 99)", notification.Message);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            var service = new NotificationService();
            var ex = Record.Exception(() =>
            {
                service.Dispose();
                service.Dispose();
            });
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageContainsNew()
        {
            // Act
            _sut.SendNotification("Instructor", "7", "Dr. Brown", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.StartsWith("New ", notification.Message);
        }
    }
}

using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(1, result[0]);
            Assert.Equal(10, result[9]);
        }

        [Fact]
        public void Create_MiddlePage_ReturnsCorrectItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(3, result.PageIndex);
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void TotalPages_ExactDivision_CorrectCount()
        {
            var source = Enumerable.Range(1, 30).AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void TotalPages_PartialLastPage_RoundsUp()
        {
            var source = Enumerable.Range(1, 31).AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(4, result.TotalPages);
        }

        [Fact]
        public void Create_SingleItem_SinglePage()
        {
            var source = new[] { 42 }.AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Single(result);
            Assert.Equal(42, result[0]);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_EmptyResult()
        {
            var source = Enumerable.Empty<int>().AsQueryable();
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            var items = new List<string> { "a", "b", "c" };
            var list = new PaginatedList<string>(items, count: 15, pageIndex: 2, pageSize: 5);

            Assert.Equal(3, list.Count);
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(3, list.TotalPages);
            Assert.True(list.HasPreviousPage);
            Assert.True(list.HasNextPage);
        }
    }
}

